    if(scene===1){
      view=0;
      if(u<0.25){x=-1.7+0.7*(u/0.25);focus=-1;}
      else if(u<0.42){x=-1;focus=-1;hold=true;}
      else if(u<0.58){x=-1+2*((u-0.42)/0.16);focus=x<0? -1:1;}
      else if(u<0.78){x=1;focus=1;hold=true;}
      else {x=1-0.7*((u-0.78)/0.22);focus=1;}
    }
    if(scene===2){x=-2+4*u;view=u>0.55?1:0;}
  }else{
    x=xin;view=vin;focus=Math.abs(x+1)<=Math.abs(x-1)?-1:1;
  }
  x=clamp(x,-2,2);
  var f=function(q){return q*q*q-3*q;};
  var d=function(q){return 3*q*q-3;};
  var fx=f(x),dx=d(x);
  var atL=Math.abs(x+1)<1e-9,atR=Math.abs(x-1)<1e-9;
