  if(scene===1 && (mode==='explore'||hold)){
    var lo=Math.min(focus-0.72,x-0.18),hi=Math.max(focus+0.72,x+0.18);
    xmin=Math.max(-2,lo);xmax=Math.min(2,hi);
    var flo=f(xmin),fhi=f(xmax),pad=0.38;
    ymin=Math.min(flo,fhi,fx)-pad;ymax=Math.max(flo,fhi,fx)+pad;
  }
  var plot={l:55,r:610,top:105,bot:395};
  function X(q){return plot.l+(q-xmin)/(xmax-xmin)*(plot.r-plot.l);}
  function Y(y){return plot.bot-(y-ymin)/(ymax-ymin)*(plot.bot-plot.top);}
  ctx.clearRect(0,0,W,H);box(0,0,W,H,'#fbfcf7');box(35,85,890,335,'#eef4ef');
  var st=scene===0?'S1 当前位置与切线':scene===1?'S2 放大驻点':'S3 符号表总结';
  text(st,635,103,19,'#41615a');text('f(x)=x³−3x',635,135,22);text('f′(x)=3x²−3',635,164,21);
  text('x='+x.toFixed(2)+'，f='+fx.toFixed(2),635,195,18);
  text('f′(x)='+dx.toFixed(2),635,222,18,sign>0?'#13795b':sign<0?'#b23a48':'#805500');
  text(sign>0?'切线斜率为正':sign<0?'切线斜率为负':'切线水平',635,249,17,sign>0?'#13795b':sign<0?'#b23a48':'#805500');
  text('符号区间：'+interval,635,276,17);
  if(atL)text('x=-1：左正右负，局部极大',635,303,17,'#805500');
  else if(atR)text('x=1：左负右正，局部极小',635,303,17,'#805500');
  else text(sign>0?'区间内函数递增':'区间内函数递减',635,303,17,sign>0?'#13795b':'#b23a48');
  ctx.save();ctx.beginPath();ctx.rect(plot.l,plot.top,plot.r-plot.l,plot.bot-plot.top);ctx.clip();
  if(view===0){
    var y0=Y(0),x0=X(0);
    if(y0>=plot.top&&y0<=plot.bot)line(plot.l,y0,plot.r,y0,'#52636b',1.5);
    if(x0>=plot.l&&x0<=plot.r)line(x0,plot.top,x0,plot.bot,'#52636b',1.5);
    var step=scene===1?0.25:1;
    for(var q=Math.ceil(xmin/step)*step;q<=xmax+1e-7;q+=step){
      if(q>=-2&&q<=2){var xp=X(q);line(xp,y0-4,xp,y0+4,'#52636b',1);if(Math.abs(q-Math.round(q))<1e-7)text(String(Math.round(q)),xp,y0+20,15,'#52636b','center');}
    }
    ctx.strokeStyle='#176b87';ctx.lineWidth=3;ctx.beginPath();
    for(var i=0;i<=320;i++){var q2=xmin+(xmax-xmin)*i/320;var yy=Y(f(q2));if(i===0)ctx.moveTo(X(q2),yy);else ctx.lineTo(X(q2),yy);}ctx.stroke();
    ctx.strokeStyle='#d26a3a';ctx.lineWidth=2;ctx.beginPath();
    ctx.moveTo(X(xmin),Y(fx+dx*(xmin-x)));ctx.lineTo(X(xmax),Y(fx+dx*(xmax-x)));ctx.stroke();
    var px=X(x),py=Y(fx);ctx.fillStyle='#d22f45';ctx.beginPath();ctx.arc(px,py,6,0,Math.PI*2);ctx.fill();
    text('P('+x.toFixed(2)+','+fx.toFixed(2)+')',Math.min(px+10,520),Math.max(plot.top+15,py-16),16,'#b12a3d');
    if(stationary)text('水平切线',Math.min(px+12,520),Math.min(plot.bot-15,py+20),16,'#805500');
    if(scene===1)text('放大视窗',plot.l+8,plot.top+17,15,'#52636b');
    if(scene===1){
      var bandY=plot.bot-42,xf=X(focus);
      var leftCol=focus===-1?'#b9e5cf':'#f4c4c4',rightCol=focus===-1?'#f4c4c4':'#b9e5cf';
      box(plot.l,bandY,xf-plot.l,leftCol);box(xf,bandY,plot.r-xf,rightCol);
      text(focus===-1?'+':'−',plot.l+(xf-plot.l)/2,bandY+15,20,focus===-1?'#176b4b':'#9d3040','center');
      text(focus===-1?'−':'+',xf+(plot.r-xf)/2,bandY+15,20,focus===-1?'#9d3040':'#176b4b','center');
      text('左侧',plot.l+(xf-plot.l)/2,bandY-14,15,'#52636b','center');text('右侧',xf+(plot.r-xf)/2,bandY-14,15,'#52636b','center');
    }
  }else{
    var by=220,a=X(-1),b=X(1);box(plot.l,by,a-plot.l,'#b9e5cf');box(a,by,b-a,'#f4c4c4');box(b,by,plot.r-b,'#b9e5cf');
    text('＋ 递增',plot.l+(a-plot.l)/2,by+24,18,'#176b4b','center');text('− 递减',(a+b)/2,by+24,18,'#9d3040','center');text('＋ 递增',b+(plot.r-b)/2,by+24,18,'#176b4b','center');
    text('[-2,-1)',plot.l+(a-plot.l)/2,by-18,16,'#52636b','center');text('(-1,1)',(a+b)/2,by-18,16,'#52636b','center');text('(1,2]',b+(plot.r-b)/2,by-18,16,'#52636b','center');
    line(plot.l,by+72,plot.r,by+72,'#52636b',2);line(a,by+64,a,by+80,'#52636b',2);line(b,by+64,b,by+80,'#52636b',2);line(X(x),by-8,X(x),by+58,'#805500',2);text('当前位置',X(x),by-25,15,'#805500','center');
  }
  ctx.restore();
  text(view===0?'图像视图':'导数符号带视图',635,335,18,'#41615a');
  text('正号对应递增，负号对应递减',635,363,16,'#52636b');
  text('导数为零还要看两侧变号',635,389,16,'#52636b');
  var title,caption;
  if(mode==='presentation'){
    title=scene===0?'切线斜率与函数走势':scene===1?'驻点与局部极值':'用符号表概括增减';
    caption=scene===0?(sign>0?'切线斜率为正，所在符号区间递增。':sign<0?'切线斜率为负，所在符号区间递减。':'切线水平，继续比较两侧符号。'):scene===1?(atL?'x=-1 左正右负，是局部极大。':atR?'x=1 左负右正，是局部极小。':'放大驻点附近，比较左右颜色的导数符号。'):'[-2,2] 内先增、后减、再增；两驻点由两侧变号判定极值。';
  }else{
    title=view===0?'图像探索：导数符号与走势':'符号带探索：增减区间';
    caption=atL?'当前恰为 x=-1：左正右负，是局部极大。':atR?'当前恰为 x=1：左负右正，是局部极小。':sign>0?'当前切线斜率为正，所在区间递增。':sign<0?'当前切线斜率为负，所在区间递减。':'当前为驻点；仅凭导数为零不能断定极值。';
  }
  return {metrics:{x:x,f:fx,derivative:dx,view:view,scene:scene,stationary:stationary,atLeft:atL,atRight:atR,focus:focus,viewport:{xmin:xmin,xmax:xmax,ymin:ymin,ymax:ymax}},controls:{x:x,view:view},disabled:{},title:title,caption:caption};
}
